REPLACE INTO `p7_employees` (`id`, `name`, `type`, `position`, `education`, `year_graduated`, `photo`, `description`, `tmt_tugas`, `slug`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(1, 'Hj. Nanik Herlinawati, M.Pd', 'kepsek', 'Kepala Sekolah', 'S2 - Manajemen Pendidikan', '2016', 'nanik.webp', 'Assalamu’alaikum warahmatullahi wabarakatuh,\r\n<br/><br/>\r\nPuji syukur kita panjatkan ke hadirat Allah SWT, karena atas rahmat dan karunia-Nya, SDN Pengasinan VII Kecamatan Rawalumbu Kota Bekasi dapat terus berkembang dalam memberikan layanan pendidikan terbaik bagi putra-putri bangsa.\r\n<br/><br/>\r\nWebsite sekolah ini merupakan salah satu wujud komitmen kami dalam menghadirkan transparansi informasi, memperluas akses komunikasi, serta mendukung pembelajaran berbasis teknologi. Inisiatif ini dimulai oleh tim IT sekolah sejak akhir tahun 2025, dan alhamdulillah dapat diselesaikan pada bulan Juni 2026. Kehadiran website ini diharapkan menjadi jendela informasi yang bermanfaat bagi seluruh warga sekolah, orang tua, dan masyarakat luas.\r\n<br/><br/>\r\nKami percaya bahwa pendidikan bukan hanya tentang transfer ilmu, tetapi juga tentang membangun karakter, kreativitas, dan semangat kebersamaan. Semoga dengan adanya website ini, SDN Pengasinan VII semakin dikenal sebagai sekolah yang unggul, berintegritas, dan selalu berusaha memberikan yang terbaik bagi generasi penerus bangsa.\r\n<br/><br/>\r\nWassalamu’alaikum warahmatullahi wabarakatuh.', '1990-05-01', 'nanik-herlinawati', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(2, 'Aep Saepudin, S.Pd.', 'teacher', 'Guru Kelas 4A', 'S1 - PGSD', '2006', 'aep.webp', 'Assalamu’alaikum, saya Aep Saepudin, guru kelas 4A. Saya menyelesaikan pendidikan di jurusan PGSD dan lulus pada tahun 2006. Sejak 1 Maret 1991, saya mulai menjalani tugas sebagai pendidik dengan penuh semangat dan dedikasi.\r\n<br/><br/>\r\nSelama perjalanan panjang di dunia pendidikan, saya banyak belajar bahwa setiap anak memiliki potensi unik yang perlu digali. Saya berusaha menghadirkan suasana kelas yang aktif, menyenangkan, dan penuh motivasi agar siswa merasa nyaman untuk bertanya dan bereksplorasi.\r\n<br/><br/>\r\nBagi saya, menjadi guru bukan hanya menyampaikan materi, tetapi juga membentuk karakter dan menumbuhkan rasa percaya diri. Harapan saya, anak-anak dapat tumbuh menjadi pribadi yang berprestasi sekaligus berakhlak mulia.', '1991-03-01', 'aep-saepudin', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(3, 'Sapariyah, S.Pd.', 'teacher', 'Guru Kelas 3A', 'S1 - PGSD', '2015', 'sapariyah.webp', 'Perkenalkan, saya Sapariyah, guru kelas 3A. Saya lulusan PGSD tahun 2015 dan mulai bertugas sejak 28 Januari 1993. Dunia pendidikan telah menjadi bagian penting dalam hidup saya, dan saya merasa bangga bisa mendampingi anak-anak di masa pertumbuhan mereka.\r\n<br/><br/>\r\nSaya percaya bahwa proses belajar di kelas haruslah menyenangkan dan penuh perhatian. Dengan pendekatan yang hangat, saya berusaha mendorong siswa untuk berani bertanya, berkreasi, dan menemukan cara belajar yang sesuai dengan diri mereka.\r\n<br/><br/>\r\nTujuan saya adalah membantu anak-anak tumbuh menjadi pribadi yang mandiri, percaya diri, dan siap menghadapi tantangan di masa depan.', '1993-01-28', 'sapariyah', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(4, 'Rohmat Nasrul Hidayat, S.Pd.I', 'teacher', 'Guru Kelas 5B', 'S1 - PAI', '2004', 'rohmat.webp', 'Saya Rohmat Nasrul Hidayat, guru kelas 5B. Saya menempuh pendidikan di jurusan PAI dan lulus tahun 2004. Sejak 1 Desember 1995, saya mulai mengabdikan diri di dunia pendidikan dengan tekad untuk menanamkan ilmu sekaligus nilai-nilai kehidupan.\r\n<br/><br/>\r\nMengajar bagi saya adalah panggilan hati. Saya berusaha menanamkan nilai keislaman, membimbing siswa agar memiliki akhlak mulia, serta menumbuhkan semangat belajar yang tinggi.\r\n<br/><br/>\r\nSaya yakin bahwa pendidikan agama tidak hanya membentuk pengetahuan, tetapi juga membangun karakter yang kuat. Dengan itu, saya berharap siswa dapat tumbuh menjadi generasi yang beriman dan berakhlak baik.', '1995-12-01', 'rohmat-nasrul-hidayat', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(5, 'Musliman, S.Pd.', 'teacher', 'Guru Kelas 4B', 'S1 - PGSD', '2015', 'musliman.webp', 'Assalamu’alaikum, saya Musliman, guru kelas 4B. Saya lulusan PGSD tahun 2015 dan mulai bertugas sejak 1 Maret 2000. Sejak awal, saya menekuni dunia pendidikan dengan keyakinan bahwa guru adalah pembimbing sekaligus teladan bagi siswa.\r\n<br/><br/>\r\nSaya percaya bahwa pendidikan dasar adalah fondasi penting bagi masa depan anak. Oleh karena itu, saya berusaha menghadirkan pembelajaran yang menyenangkan, interaktif, dan membangun rasa percaya diri siswa.\r\n<br/><br/>\r\nDengan semangat kebersamaan, saya ingin setiap anak merasa dihargai dan mampu mengembangkan potensi terbaiknya.', '2000-03-01', 'musliman', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(6, 'Kusniyati, S.Pd.', 'teacher', 'Guru Kelas 6B', 'S1 - PGSD', '2006', 'kusniyati.webp', 'Perkenalkan, saya Kusniyati, guru kelas 6B. Saya menyelesaikan pendidikan di jurusan PGSD tahun 2006 dan mulai bertugas sejak 1 Desember 2002. Dunia pendidikan telah memberi saya kesempatan untuk mendampingi siswa di masa transisi menuju jenjang berikutnya.\r\n<br/><br/>\r\nSebagai guru kelas akhir, saya berkomitmen membekali siswa dengan pengetahuan dan keterampilan yang akan membantu mereka melanjutkan ke tingkat lebih tinggi. Saya ingin setiap anak meninggalkan sekolah dasar dengan rasa percaya diri dan kesiapan menghadapi masa depan.\r\n<br/><br/>\r\nSaya percaya bahwa dengan dukungan dan motivasi yang tepat, setiap siswa mampu meraih prestasi sekaligus menjadi pribadi yang tangguh.', '2002-12-01', 'kusniyati', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(7, 'Saroh Wijiastuti, S.Pd.SD', 'teacher', 'Guru Kelas 1A & 2A', 'S1 - PGSD', '2011', 'saroh.webp', 'Saya Saroh Wijiastuti, guru kelas 1A dan 2A. Saya lulusan PGSD tahun 2011 dan mulai bertugas sejak 1 April 2006. Mengajar siswa kelas awal adalah tantangan sekaligus kebahagiaan tersendiri bagi saya.\r\n<br/><br/>\r\nSaya berusaha menanamkan dasar-dasar membaca, menulis, berhitung, serta membentuk karakter disiplin dan rasa ingin tahu sejak dini. Dengan pendekatan yang penuh kesabaran, saya ingin anak-anak merasa senang belajar dan berani mencoba hal baru.\r\n<br/><br/>\r\nHarapan saya, siswa dapat tumbuh menjadi pribadi yang mandiri, bersemangat, dan siap melanjutkan perjalanan pendidikan mereka.', '2006-04-01', 'saroh-wijiastuti', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(8, 'Hestiani, S.Pd.', 'teacher', 'Guru Kelas 5B', 'S1 - PPKn', '2013', 'hestiani.webp', 'Assalamu’alaikum, saya Hestiani, guru kelas 5B. Saya lulusan PPKn tahun 2013 dan mulai bertugas sejak 1 Juli 2003. Sejak awal, saya menekuni dunia pendidikan dengan tekad untuk menanamkan ilmu sekaligus nilai kebangsaan.\r\n<br/><br/>\r\nSaya berkomitmen menanamkan nilai demokrasi, cinta tanah air, dan kebersamaan melalui pembelajaran yang interaktif. Saya percaya bahwa pendidikan bukan hanya soal akademik, tetapi juga membentuk sikap dan karakter siswa.\r\n<br/><br/>\r\nDengan semangat kebangsaan, saya berharap siswa dapat tumbuh menjadi generasi yang cerdas, peduli, dan bertanggung jawab.\r\n\r\n', '2003-07-01', 'hestiani', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(9, 'Heni Widyana, S.Pd.', 'teacher', 'Guru Kelas 1C & 2C', 'S1 - PGSD', '2018', 'heni.webp', 'Perkenalkan, saya Heni Widyana, guru kelas 1C dan 2C. Saya lulusan PGSD tahun 2018 dan mulai bertugas sejak 1 Januari 2008. Mengajar siswa kelas awal memberi saya kesempatan untuk mendampingi anak-anak di masa paling penting dalam perkembangan mereka.\r\n<br/><br/>\r\nSaya berusaha menciptakan suasana belajar yang penuh kasih sayang, mendukung perkembangan dasar anak, dan membangun rasa percaya diri. Saya ingin setiap siswa merasa senang datang ke sekolah dan termotivasi untuk belajar.\r\n<br/><br/>\r\nDengan pendekatan yang hangat, saya berharap siswa dapat tumbuh menjadi pribadi yang mandiri, bersemangat, dan siap menghadapi tantangan di masa depan.', '2008-01-01', 'heni-widyana', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(10, 'Silviyatun, S.Pd.I', 'teacher', 'Guru PAI Kelas 4-6', 'S1 - Kependidikan Islam', '2004', 'silviyatun.webp', 'Saya Silviyatun, guru Pendidikan Agama Islam untuk kelas 4–6. Saya lulusan Kependidikan Islam tahun 2004 dan mulai bertugas sejak 1 Juli 2005. Dunia pendidikan agama memberi saya kesempatan untuk menanamkan nilai spiritual dan moral kepada siswa.\r\n<br/><br/>\r\nMengajar PAI bagi saya adalah kesempatan untuk membimbing siswa agar memiliki akhlak mulia, semangat belajar, dan rasa tanggung jawab. Saya percaya bahwa pendidikan agama adalah pondasi penting dalam membentuk karakter.\r\n<br/><br/>\r\nHarapan saya, anak-anak dapat tumbuh menjadi generasi yang beriman, berakhlak baik, dan siap menghadapi tantangan zaman dengan bekal nilai-nilai kehidupan yang kuat.', '2005-07-01', 'silviyatun', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(11, 'Marina Sarrizki, S.Pd', 'teacher', 'Guru Kelas 3C', 'S1 - PGSD', '2019', 'marina.webp', 'Perkenalkan, saya Marina Sarrizki, guru kelas 3C. Saya lulusan PGSD tahun 2019 dan mulai bertugas sejak 1 Agustus 2008. Dunia pendidikan telah menjadi jalan hidup saya, dan saya merasa bangga bisa mendampingi anak-anak di masa pertumbuhan mereka.\r\n<br/><br/>\r\nSaya percaya bahwa setiap anak memiliki cara belajar yang berbeda. Oleh karena itu, saya berusaha menciptakan suasana kelas yang kondusif, penuh perhatian, dan mendorong siswa untuk berani bertanya serta berkreasi.\r\n<br/><br/>\r\nHarapan saya adalah membantu anak-anak tumbuh menjadi pribadi yang mandiri, percaya diri, dan siap menghadapi tantangan di masa depan.', '2008-08-01', 'marina-sarrizki', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(12, 'Romadhona Aidin, S.Pd.', 'teacher', 'Guru PJOK Kelas 1-3', 'S1 - PJOK', '2015', 'romadhona.webp', 'Saya Romadhona Aidin, guru PJOK untuk kelas 1–3. Saya lulusan PJOK tahun 2015 dan mulai bertugas sejak 2 Januari 2017. Sejak awal, saya menekuni bidang olahraga dengan keyakinan bahwa kesehatan jasmani adalah fondasi penting bagi perkembangan anak.\r\n<br/><br/>\r\nSaya berusaha menghadirkan pembelajaran PJOK yang menyenangkan, interaktif, dan membangun semangat kebersamaan. Dengan pendekatan yang penuh motivasi, saya ingin siswa merasa senang bergerak dan berolahraga.\r\n<br/><br/>\r\nHarapan saya, anak-anak dapat tumbuh menjadi pribadi yang sehat, aktif, dan memiliki karakter sportif.', '2017-01-02', 'romadhona-aidin', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(13, 'Intan Prawesti, S.Pd', 'teacher', 'Guru Kelas', 'S1 - PGSD', '2011', 'intan.webp', 'Assalamu’alaikum, saya Intan Prawesti, guru kelas. Saya lulusan PGSD tahun 2011 dan mulai bertugas sejak 12 Juli 2010. Dunia pendidikan memberi saya kesempatan untuk mendampingi siswa dalam proses belajar dan membentuk karakter mereka.\r\n<br/><br/>\r\nSaya percaya bahwa guru bukan hanya penyampai ilmu, tetapi juga pembimbing yang menanamkan nilai-nilai kehidupan. Dengan pendekatan yang hangat, saya berusaha menciptakan suasana kelas yang menyenangkan dan penuh semangat.\r\n<br/><br/>\r\nHarapan saya adalah membantu siswa tumbuh menjadi pribadi yang berprestasi, mandiri, dan berakhlak mulia.', '2010-07-12', 'intan-prawesti', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(14, 'Adnan Zaki, S.Kom', 'staff', 'Pengelola Sistem Informasi', 'S1 - Teknik Informatika', '2018', 'zaki.webp', 'Perkenalkan, saya Adnan Zaki, staf pengelola sistem informasi. Saya merupakan lulusan Teknik Informatika tahun 2018 dan mulai bertugas sejak 1 Juli 2013. Dunia teknologi informasi telah menjadi bidang yang saya tekuni untuk mendukung kelancaran administrasi dan sistem sekolah. \r\n<br/><br/> \r\nSaya berkomitmen menghadirkan solusi digital yang efektif, menjaga keamanan data, serta memastikan sistem informasi berjalan dengan baik. Dengan pengalaman di bidang IT baik itu mengembangkan website maupun membangun aplikasi berbasis web, saya berusaha memberikan layanan yang optimal bagi seluruh civitas sekolah. \r\n<br/><br/> \r\nSaat ini, saya aktif mengembangkan website resmi SDN Pengasinan VII. Selain itu saya juga mengembangkan aplikasi tata kelola dan <i>generator</i>  surat yaitu <a href="https://surpress.sdnpengasinan7.sch.id/"><strong>Surpress</strong> </a>, yang saat ini juga aktif digunakan di SDN Pengasinan VII.\r\n<br/><br/> \r\nSementara untuk mendukung kinerja guru dalam mengolah nilai rapor, saya mengimplementasikan aplikasi <a href="https://rapor.sdnpengasinan7.sch.id/"><strong>eRaporSD</strong> </a>  yang dirilis oleh Kemendikdasmen agar bisa diakses secara publik oleh seluruh guru tanpa harus berada di dalam lingkungan sekolah.\r\n<br/><br/> \r\nHarapan saya adalah mendukung terciptanya lingkungan pendidikan yang modern, efisien, dan siap menghadapi perkembangan teknologi.\r\n', '2013-07-01', 'adnan-zaki', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(15, 'Darmanto, S.Pd.I', 'teacher', 'Guru PAI Kelas 1-3', 'S1 - PAI', '2012', 'darmanto.webp', 'Saya Darmanto, guru Pendidikan Agama Islam untuk kelas 1–3. Saya lulusan PAI tahun 2012 dan mulai bertugas sejak 19 Juli 2013. Mengajar agama bagi saya adalah kesempatan untuk menanamkan nilai spiritual sejak dini.\r\n<br/><br/>\r\nSaya berusaha membimbing siswa agar memiliki akhlak mulia, semangat belajar, dan rasa tanggung jawab. Dengan pendekatan yang penuh kesabaran, saya ingin anak-anak merasa senang belajar agama.\r\n<br/><br/>\r\nHarapan saya adalah membentuk generasi yang beriman, berakhlak baik, dan siap menghadapi tantangan zaman.', '2013-07-19', 'darmanto', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(16, 'Rina Rosinta, S.Pd', 'teacher', 'Guru Kelas 1B & 2B', 'S1 - PGSD', '2024', 'rina.webp', 'Perkenalkan, saya Rina Rosinta, guru kelas 1B dan 2B. Saya lulusan PGSD tahun 2024 dan mulai bertugas sejak 15 Maret 2019. Mengajar siswa kelas awal memberi saya kesempatan untuk mendampingi anak-anak di masa paling penting dalam perkembangan mereka.\r\n<br/><br/>\r\nSaya berusaha menciptakan suasana belajar yang penuh kasih sayang, mendukung perkembangan dasar anak, dan membangun rasa percaya diri. Saya ingin setiap siswa merasa senang datang ke sekolah dan termotivasi untuk belajar.\r\n<br/><br/>\r\nDengan pendekatan yang hangat, saya berharap siswa dapat tumbuh menjadi pribadi yang mandiri, bersemangat, dan siap menghadapi masa depan.', '2019-03-15', 'rina-rosinta', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(17, 'M. Insan Maulana Ibrahim, S.A.p', 'staff', 'Staff Kesiswaan dan Kepegawaian', 'S1 - Administrasi Publik', '2022', 'insan.webp', 'Saya Muhamad Insan Maulana Ibrahim, staf kesiswaan dan kepegawaian. Saya lulusan Administrasi Publik tahun 2022. Dunia administrasi memberi saya kesempatan untuk mendukung kelancaran kegiatan sekolah dari sisi manajemen.\r\n<br/><br/>\r\nSaya berkomitmen memberikan pelayanan yang baik, menjaga ketertiban administrasi, serta membantu kebutuhan siswa dan tenaga pendidik. Dengan semangat kerja sama, saya ingin menciptakan lingkungan yang tertib dan nyaman.\r\n<br/><br/>\r\nHarapan saya adalah mendukung terciptanya sistem administrasi yang profesional, transparan, dan bermanfaat bagi semua pihak.', '2021-08-06', 'insan-maulana-ibrahim', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(18, 'Fahrianto, S.Pd.', 'teacher', 'Guru PJOK Kelas 4-6', 'S1 - PJOK', '2021', 'fahrianto.webp', 'Assalamu’alaikum, saya Fahrianto, guru PJOK untuk kelas 4–6. Saya lulusan PJOK tahun 2021 dan mulai bertugas sejak 1 Juli 2021. Bidang olahraga adalah passion saya, dan saya percaya bahwa kesehatan jasmani sangat penting bagi perkembangan anak.\r\n<br/><br/>\r\nSaya berusaha menghadirkan pembelajaran PJOK yang menyenangkan, membangun semangat kebersamaan, dan menanamkan nilai sportifitas. Dengan pendekatan yang penuh motivasi, saya ingin siswa merasa senang bergerak dan berolahraga.\r\n<br/><br/>\r\nHarapan saya adalah membentuk generasi yang sehat, aktif, dan memiliki karakter tangguh.', '2021-07-01', 'fahrianto', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(19, 'Suci Khamila Dewi', 'teacher', 'Guru Kelas 3B', 'SMK', '2019', 'dewi.webp', 'Perkenalkan, saya Suci Khamila Dewi, guru kelas 3B. Saya lulusan SMK tahun 2019 dan mulai bertugas sejak 1 Juli 2021. Dunia pendidikan memberi saya kesempatan untuk mendampingi siswa dalam proses belajar dan tumbuh kembang mereka.\r\n<br/><br/>\r\nSaya berusaha menciptakan suasana kelas yang menyenangkan, penuh perhatian, dan mendorong siswa untuk berani bertanya serta berkreasi. Dengan pendekatan yang hangat, saya ingin anak-anak merasa nyaman belajar.\r\n<br/><br/>\r\nHarapan saya adalah membantu siswa tumbuh menjadi pribadi yang mandiri, percaya diri, dan siap menghadapi masa depan.', '2021-07-01', 'suci-khamila-dewi', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(20, 'Mohamad Sholeh', 'staff', 'Petugas Kebersihan', 'SD', '1988', 'sholeh.webp', 'Saya Mohamad Sholeh, staf petugas kebersihan. Saya lulusan SD tahun 1988 dan resmi bertugas di SDN Pengasinan VII sejak 15 Juli 2025 setelah sebelumnya mengabdi di SDN Sepanjang Jaya IV. Sejak awal bertugas, saya berkomitmen menjaga kebersihan lingkungan sekolah agar tetap nyaman dan sehat bagi seluruh warga sekolah.\r\n<br/><br/>\r\nSaya percaya bahwa kebersihan adalah bagian penting dari proses belajar. Dengan lingkungan yang bersih, siswa dan guru dapat beraktivitas dengan lebih baik.\r\n<br/><br/>\r\nHarapan saya adalah mendukung terciptanya suasana sekolah yang sehat, tertib, dan menyenangkan.', '2025-07-15', 'mohamad-sholeh', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL),
	(21, 'Muhammad Jamatullail Siraj', 'staff', 'Pustakawan', 'SMK', '2025', 'siraj.webp', 'Perkenalkan, saya Muhammad Jamatullail Siraj, pustakawan SDN Pengasinan VII. Saya merupakan lulusan SMK tahun 2025 dan mulai bekerja di SDN Pengasinan VII sejak 6 Februari 2026. Dunia literasi memberi saya kesempatan untuk mendukung siswa dan guru dalam mengakses pengetahuan.\r\n<br/><br/>\r\nSaya berkomitmen menjaga koleksi buku, membantu siswa menemukan referensi, serta menciptakan suasana perpustakaan yang nyaman. Dengan semangat literasi, saya ingin menumbuhkan minat baca di kalangan siswa.\r\n<br/><br/>\r\nHarapan saya adalah mendukung terciptanya budaya membaca yang kuat, sehingga siswa dapat tumbuh menjadi generasi yang cerdas dan berwawasan luas.', '2026-02-06', 'muhammad-jamatullail-siraj', '2026-04-30 14:35:00', '2026-04-30 14:35:00', NULL);
