	(6, 1, '2026-05-27 16:28:21', '2026-05-27 16:28:21', '<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->', 'Hello world!', '', 'inherit', 'closed', 'closed', '', '1-revision-v1', '', '', '2026-05-27 16:28:21', '2026-05-27 16:28:21', '', 1, 'http://localhost/pengasinan7-website/cms/?p=6', 0, 'revision', '', 0),
	(7, 1, '2026-04-22 16:36:16', '2026-04-22 16:36:16', '<!-- wp:paragraph -->\n<p>SDN Pengasinan VII kembali melaksanakan <strong>Tes Kemampuan Akademik (TKA)</strong> sebagai bagian dari proses penerimaan peserta didik baru tahun ajaran 2026/2027. Kegiatan ini bertujuan untuk mengukur kesiapan akademik calon siswa dalam menghadapi jenjang pendidikan dasar. Tes dilaksanakan secara tertib di ruang kelas yang telah disiapkan dengan pengawasan guru dan panitia PPDB. Hasil TKA akan menjadi salah satu acuan dalam penempatan kelas dan program pembinaan awal bagi siswa baru.</p>\n<!-- /wp:paragraph -->', 'Pelaksanaan Tes Kemampuan Akademik Tahun Ajaran 2026/2027', '', 'publish', 'open', 'open', '', 'pelaksanaan-tes-kemampuan-akademik', '', '', '2026-05-27 17:19:32', '2026-05-27 17:19:32', '', 0, 'http://localhost/pengasinan7-website/cms/?p=7', 0, 'post', '', 0),
	(8, 1, '2026-05-27 16:28:24', '2026-05-27 16:28:24', '{"version": 3, "isGlobalStylesUserThemeJSON": true }', 'Custom Styles', '', 'publish', 'closed', 'closed', '', 'wp-global-styles-twentytwentyfive', '', '', '2026-05-27 16:28:24', '2026-05-27 16:28:24', '', 0, 'http://localhost/pengasinan7-website/cms/2026/05/27/wp-global-styles-twentytwentyfive/', 0, 'wp_global_styles', '', 0),
